class Solution:
    def sumOfPerfectSquareAncestors(self, n: int, edges: list[list[int]], nums: list[int]) -> int:
        M = 100001
        spf = list(range(M))
        i = 2
        while i * i < M:
            if spf[i] == i:
                for j in range(i * i, M, i):
                    if spf[j] == j: spf[j] = i
            i += 1
        def ker(x):
            r = 1
            while x > 1:
                p = spf[x]
                c = 0
                while x % p == 0: x //= p; c += 1
                if c & 1: r *= p
            return r
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        key = [ker(x) for x in nums]
        from collections import defaultdict
        cnt = defaultdict(int)
        ans = 0
        stack = [(0, -1, False)]
        while stack:
            u, par, done = stack.pop()
            if done:
                cnt[key[u]] -= 1
                continue
            ans += cnt[key[u]]
            cnt[key[u]] += 1
            stack.append((u, par, True))
            for w in adj[u]:
                if w != par: stack.append((w, u, False))
        return ans

