class Solution {
public:
    int sumOfPerfectSquareAncestors(int n, vector<vector<int>>& edges, vector<int>& nums) {
        const int M = 100001;
        vector<int> spf(M); iota(spf.begin(), spf.end(), 0);
        for (int i = 2; i * i < M; i++)
            if (spf[i] == i)
                for (int j = i * i; j < M; j += i)
                    if (spf[j] == j) spf[j] = i;
        auto ker = [&](int x) {
            long long r = 1;
            while (x > 1) {
                int p = spf[x], c = 0;
                while (x % p == 0) { x /= p; c++; }
                if (c & 1) r *= p;
            }
            return r;
        };
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        vector<long long> key(n);
        for (int i = 0; i < n; i++) key[i] = ker(nums[i]);
        unordered_map<long long,int> cnt;
        long long ans = 0;
        vector<array<int,3>> st = {{0, -1, 0}};
        while (!st.empty()) {
            auto [u, par, done] = st.back(); st.pop_back();
            if (done) { cnt[key[u]]--; continue; }
            ans += cnt[key[u]]++;
            st.push_back({u, par, 1});
            for (int w : adj[u]) if (w != par) st.push_back({w, u, 0});
        }
        return (int)ans;
    }
};

