class Solution {
    public int sumOfPerfectSquareAncestors(int n, int[][] edges, int[] nums) {
        final int M = 100001;
        int[] spf = new int[M];
        for (int i = 0; i < M; i++) spf[i] = i;
        for (int i = 2; (long) i * i < M; i++)
            if (spf[i] == i)
                for (int j = i * i; j < M; j += i)
                    if (spf[j] == j) spf[j] = i;
        long[] key = new long[n];
        for (int i = 0; i < n; i++) {
            int x = nums[i]; long r = 1;
            while (x > 1) {
                int p = spf[x], c = 0;
                while (x % p == 0) { x /= p; c++; }
                if (c % 2 == 1) r *= p;
            }
            key[i] = r;
        }
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        Map<Long,Integer> cnt = new HashMap<>();
        long ans = 0;
        Deque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{0, -1, 0});
        while (!st.isEmpty()) {
            int[] top = st.pop();
            int u = top[0], par = top[1], done = top[2];
            if (done == 1) { cnt.merge(key[u], -1, Integer::sum); continue; }
            ans += cnt.getOrDefault(key[u], 0);
            cnt.merge(key[u], 1, Integer::sum);
            st.push(new int[]{u, par, 1});
            for (int w : adj.get(u)) if (w != par) st.push(new int[]{w, u, 0});
        }
        return (int) ans;
    }
}

