var sumOfPerfectSquareAncestors = function(n, edges, nums) {
    const M = 100001, spf = Array.from({length: M}, (_, i) => i);
    for (let i = 2; i * i < M; i++)
        if (spf[i] === i)
            for (let j = i * i; j < M; j += i)
                if (spf[j] === j) spf[j] = i;
    const ker = (x) => {
        let r = 1;
        while (x > 1) {
            const p = spf[x]; let c = 0;
            while (x % p === 0) { x /= p; c++; }
            if (c & 1) r *= p;
        }
        return r;
    };
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const key = nums.map(ker);
    const cnt = new Map();
    let ans = 0;
    const st = [[0, -1, false]];
    while (st.length) {
        const [u, par, done] = st.pop();
        if (done) { cnt.set(key[u], cnt.get(key[u]) - 1); continue; }
        ans += cnt.get(key[u]) || 0;
        cnt.set(key[u], (cnt.get(key[u]) || 0) + 1);
        st.push([u, par, true]);
        for (const w of adj[u]) if (w !== par) st.push([w, u, false]);
    }
    return ans;
};
